<script setup>
import {computed,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {daysBetween,fdate,maskMobile} from '../../lib/client-info';
import {TEMPLATES,msgVars,fillTpl,autoRules} from '../../lib/client-messages';
import {saveClientRemark} from '../../lib/client-profile-sections';
import {createClientInfoReader} from '../../api/client-info';
const props=defineProps({bundle:Object,metrics:Object});const emit=defineEmits(['busy']);
const m=props.metrics,suggested=m.due.overdue?'due':m.nextAppt&&daysBetween(m.t,m.nextAppt.appointment_date)<=1?'session_1d':['irregular','stopped'].includes(m.status)?'missed':!m.nextAppt&&m.livePlans?'next_appt':'thanks';
const template=ref(suggested),recipient=ref(0),offer=ref(''),validity=ref(''),text=ref(''),busy=ref(false),notice=ref(''),error=ref('');
const b=computed(()=>({...props.bundle,m:props.metrics}));
watch([template,offer,validity],()=>{text.value=fillTpl(TEMPLATES.find(t=>t.k===template.value).t,msgVars(b.value,{...(offer.value?{offer:offer.value}:{}),...(validity.value?{validity:fdate(validity.value)}:{})}));},{immediate:true});
const missing=computed(()=>[...new Set(text.value.match(/\{\w+\}/g)||[])]);
async function send(channel){if(busy.value)return;notice.value='';error.value='';const content=text.value.trim();if(!content){error.value='Message is empty.';return;}if(channel==='copy'){try{await navigator.clipboard.writeText(content);notice.value='Message copied.';}catch{error.value='Copy blocked by browser.';}return;}if(missing.value.length){error.value='Replace the {placeholders} first.';return;}const phone=props.metrics.phones[Number(recipient.value)];if(!phone)return;
 window.open(channel==='wa'?'https://wa.me/91'+phone.number+'?text='+encodeURIComponent(content):'sms:+91'+phone.number+'?body='+encodeURIComponent(content),'_blank','noopener');
 busy.value=true;emit('busy',true);try{const result=await saveClientRemark(createClientInfoReader(),props.bundle,'[Message] '+(channel==='wa'?'WhatsApp':'SMS')+' sent to '+phone.label+' '+maskMobile(phone.number)+': '+TEMPLATES.find(t=>t.k===template.value).l);props.bundle.patient.custom_remarks=result.patient.custom_remarks;delete props.bundle.lazy.remarks;notice.value=(channel==='wa'?'Opening WhatsApp…':'Opening SMS app…')+(result.warning?' Activity history warning: '+result.warning:'');}catch(e){error.value='Message app opened. Could not save its audit remark: '+e.message;}finally{busy.value=false;emit('busy',false);}}
onBeforeRouteLeave(()=>!busy.value);
</script>
<template><div class="c3-tab-body"><div class="c3-split c3-split-msg"><section class="c3-card"><header class="c3-card-h"><div><b>💬 Send a message</b><small>Pick a template, check the text, send from your WhatsApp or SMS.</small></div></header><label v-if="metrics.phones.length" class="c3-lbl">To<select v-model="recipient" class="c3-input" data-msg-to><option v-for="(p,i) in metrics.phones" :key="p.number" :value="i">{{p.label}}: {{maskMobile(p.number)}}</option></select></label><div v-else class="c3-alert tone-neg"><span>📵</span><p>No mobile number on the Patient record.</p></div><div class="c3-tpls" data-msg-tpls><button v-for="t in TEMPLATES" :key="t.k" type="button" class="c3-tpl" :class="{'is-on':template===t.k}" :data-k="t.k" @click="template=t.k">{{t.i}} {{t.l}} <span v-if="t.k===suggested" class="c3-pill tone-ok">Suggested</span></button></div><div v-if="template==='offer'" class="c3-grid c3-g2" data-msg-offer><label class="c3-lbl">Offer<input v-model="offer" class="c3-input" data-var="offer" placeholder="e.g. 20% off on HydraFacial"></label><label class="c3-lbl">Valid till<input v-model="validity" class="c3-input" type="date" data-var="validity"></label></div><label class="c3-lbl">Message<textarea v-model="text" class="c3-input" rows="6" data-msg-text></textarea></label><div class="c3-note" data-msg-warn><span v-if="missing.length" class="tone-warn">⚠️ Fill before sending: {{missing.join(', ')}}</span></div><div class="c3-msg-actions"><button type="button" class="c3-btn c3-btn-wa" data-send="wa" :disabled="busy||!metrics.phones.length" @click="send('wa')">🟢 Send on WhatsApp</button><button type="button" class="c3-btn" data-send="sms" :disabled="busy||!metrics.phones.length" @click="send('sms')">✉️ Send SMS</button><button type="button" class="c3-btn" data-send="copy" @click="send('copy')">📋 Copy text</button></div><p class="c3-note">Each send is logged under Remarks for audit.</p><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></section><section class="c3-card"><header class="c3-card-h"><div><b>🤖 Automatic reminders</b><small>Planned triggers for this client. They run once the messaging backend is connected.</small></div><span class="c3-pill tone-warn">⚙️ Setup pending</span></header><div class="c3-rules"><div v-for="r in autoRules(b)" :key="r.l" class="c3-rule"><span class="c3-rule-ic">{{r.i}}</span><div><b>{{r.l}}</b><small>Next for this client: {{r.next}}</small></div><span class="c3-switch is-off" title="Enable after WhatsApp/SMS gateway setup">Off</span></div></div><p class="c3-note">Automatic reminders require the configured messaging service.</p></section></div></div></template>
